import { run, step } from "zttp:durable";
import { call } from "zttp:workflow";

structural OrderWorkflow<T> = Proof<T,
  | "deterministic"
  | "retry_safe"
  | "idempotent"
  | "state_isolated"
  | "result_safe"
  | "optional_safe"
  | "no_secret_leakage"
  | "no_credential_leakage"
  | "input_validated"
  | "pii_contained"
  | "injection_safe"
  | "canonical"
  | "cost_bounded"
>;

export function handler(req: Request): OrderWorkflow<Response> {
  const key = req.headers.get("idempotency-key");
  if (key === undefined) {
    return Response.json({ error: "missing idempotency-key" }, { status: 400 });
  }
  return run(key, () => {
    const reservation = step("reserve-inventory", () => {
      return { reserved: true };
    });
    const notified = call("notify", { reservation: reservation });
    return Response.json({ notified: notified.status }, { status: 201 });
  });
}
```

Wait — one thing: `structural OrderWorkflow<T> = Proof<T, ...>` — is a structural alias to Proof allowed? The durable-wait-and-signal example presumably used `structural DurableWaitSignalWorkflow<T> = Proof<T, ...>` (that's the conventional ZTS pattern from training). Type aliases (`type` declaration) are blocked, but `structural` type declarations are allowed. Good.

Property list: which properties does the compiler require or accept? Unknown properties in the proof list would be a veto failure. From the module example catalog, durable-wait-and-signal used these properties (I recall from the bootstrap: "deterministic, retry_safe, idempotent, state_isolated, result_safe, optional_safe, no_secret_leakage, no_credential_leakage, input_validated, pii_contained, injection_safe, canonical, cost_bounded"). That was for a handler that reads req.query and calls waitSignal/signal. Mine does the same kind of work minus user-input reads. I'll claim the same set. If the veto rejects any property, it'll tell me and I'll adjust.

